
CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tools(slug TEXT PRIMARY KEY, name TEXT NOT NULL, price INTEGER, active INTEGER NOT NULL DEFAULT 1, metadata TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL COLLATE NOCASE,nickname TEXT UNIQUE NOT NULL COLLATE NOCASE,password TEXT, bio TEXT NOT NULL DEFAULT '',role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),status TEXT NOT NULL DEFAULT 'active',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS session_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS identities(provider TEXT,subject TEXT,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(provider,subject));
CREATE TABLE IF NOT EXISTS votes(id INTEGER PRIMARY KEY,slug TEXT NOT NULL REFERENCES tools(slug),user_id TEXT REFERENCES users(id) ON DELETE CASCADE,anonymous TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(slug,user_id),UNIQUE(slug,anonymous),CHECK(user_id IS NOT NULL OR anonymous IS NOT NULL));
CREATE TABLE IF NOT EXISTS posts(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,title TEXT NOT NULL,body TEXT NOT NULL,board TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '',tool_slug TEXT REFERENCES tools(slug),build TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'active',pinned INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS posts_board ON posts(status,board,created_at);
CREATE TABLE IF NOT EXISTS comments(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,parent_id TEXT REFERENCES comments(id) ON DELETE CASCADE,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS comments_post ON comments(post_id,status);
CREATE TABLE IF NOT EXISTS reactions(user_id TEXT REFERENCES users(id) ON DELETE CASCADE,post_id TEXT REFERENCES posts(id) ON DELETE CASCADE,kind TEXT CHECK(kind IN ('like','bookmark')),PRIMARY KEY(user_id,post_id,kind));
CREATE TABLE IF NOT EXISTS bookmarks(user_id TEXT REFERENCES users(id) ON DELETE CASCADE,slug TEXT REFERENCES tools(slug),PRIMARY KEY(user_id,slug));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,post_id TEXT REFERENCES posts(id) ON DELETE CASCADE,comment_id TEXT REFERENCES comments(id) ON DELETE CASCADE,label TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,target_type,target_id));
CREATE TABLE IF NOT EXISTS suggestions(id INTEGER PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,slug TEXT,title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor TEXT REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS waitlist(email TEXT PRIMARY KEY COLLATE NOCASE,token TEXT NOT NULL UNIQUE,consent TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT DEFAULT CURRENT_TIMESTAMP,withdrawn_at TEXT);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS analytics(day TEXT,event TEXT,path TEXT,count INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(day,event,path));
CREATE TABLE IF NOT EXISTS auth_tokens(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,mime TEXT NOT NULL,size INTEGER NOT NULL,storage TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);

